'use strict';
// Paired curriculum text keeps lesson IDs, quiz answers, and student work identical across languages.
const B = value => String(value).split('|');
let questionNumber = 0;
function Q(stem, correct, other1, other2, explanation) {
  const answer = questionNumber++ % 3;
  const options = [B(other1), B(other2)];
  options.splice(answer, 0, B(correct));
  return { stem: B(stem), options, answer, explanation: B(explanation) };
}
