function L(id, title, stage, bsd, goal, material, tasks, success, bcw, practice, opening, exit, pre, post) {
  return { id, title: B(title), stage, bsd, goal: B(goal), material: B(material), tasks: tasks.map(B), success: success.map(B), bcw, practice: B(practice), opening: B(opening), exit: B(exit), pre: [pre], post };
}
